python3 -c "
import sqlite3
conn=sqlite3.connect('/workspace/world.db')
tables=[t[0] for t in conn.execute(\"SELECT name FROM sqlite_master WHERE type='table'\").fetchall()]
for t in tables:
    cols=[c[1] for c in conn.execute(f'PRAGMA table_info({t})').fetchall()]
    for c in cols:
        cn = c[1]
        try:
            for term in ['deal','flight','stop']:
                rows=conn.execute(f\"SELECT * FROM {t} WHERE CAST({cn} AS TEXT) LIKE '%{term}%'\").fetchall()
                if rows:
                    print(f'{t}.{cn} has {len(rows)} rows with \"{term}\"')
                    if len(rows)<=3: print(rows)
        except: pass
